insert into storage.buckets (id,name,public,file_size_limit,allowed_mime_types) values ('herlife-private-memories','herlife-private-memories',false,47185920,ARRAY['image/jpeg','image/png','image/webp','image/heic','image/heif','video/mp4','video/quicktime','video/webm']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy "HerLife member private memory read" on storage.objects for select to authenticated using (bucket_id='herlife-private-memories' and (storage.foldername(name))[1]=(select auth.uid())::text and exists(select 1 from public.app_members where user_id=(select auth.uid())));
create policy "HerLife member private memory upload" on storage.objects for insert to authenticated with check (bucket_id='herlife-private-memories' and (storage.foldername(name))[1]=(select auth.uid())::text and exists(select 1 from public.app_members where user_id=(select auth.uid())));
create policy "HerLife member private memory delete" on storage.objects for delete to authenticated using (bucket_id='herlife-private-memories' and (storage.foldername(name))[1]=(select auth.uid())::text and exists(select 1 from public.app_members where user_id=(select auth.uid())));
